select 
from generic_policy
where type_code = #{typeCode}
  and status != 'DELETED'

  and status = #{status}


  and (
    lower(name) like concat('%', lower(#{keyword}), '%')
    or lower(coalesce(description, '')) like concat('%', lower(#{keyword}), '%')
  )

order by priority asc, id asc
limit #{limit}
offset #{offset}

select count(*)
from generic_policy
where type_code = #{typeCode}
  and status != 'DELETED'

  and status = #{status}


  and (
    lower(name) like concat('%', lower(#{keyword}), '%')
    or lower(coalesce(description, '')) like concat('%', lower(#{keyword}), '%')
  )

