mapper.update:
update generic_policy
set status = 'DELETED',
    version = version + 1,
    updated_by = #{operatorUserId},
    updated_at = #{now},
    deleted_by = #{operatorUserId},
    deleted_at = #{now}
where id = #{policyId}
  and version = #{version}
  and status != 'DELETED'

update generic_policy
set priority = #{priority},
    version = version + 1,
    updated_by = #{operatorUserId},
    updated_at = #{updatedAt}
where id = #{policyId}
  and version = #{version}
  and status != 'DELETED'
